// FlightNode represents a node in the linked list of flights
// with a pointer to the next node and the flight details
struct FlightNode {
    int flightNumber;
    FlightNode *next;
};

// Function to add a new flight to the linked list
void addFlight(FlightNode *&head, int flightNumber) {
    FlightNode *newNode = new FlightNode();
    newNode->flightNumber = flightNumber;
    newNode->next = head;
    head = newNode;
}

// Function to remove a flight from the linked list
void removeFlight(FlightNode *&head, int flightNumber) {
    if (head == nullptr)
        return;
    if (head->flightNumber == flightNumber) {
        FlightNode *temp = head;
        head = head->next;
        delete temp;
        return;
    }
    FlightNode *current = head;
    while (current->next != nullptr) {
        if (current->next->flightNumber == flightNumber) {
            FlightNode *temp = current->next;
            current->next = current->next->next;
            delete temp;
            return;
        }
        current = current->next;
    }
}

// Function to print all flights in the linked list
void printFlights(FlightNode *head) {
    FlightNode *current = head;
    while (current != nullptr) {
        std::cout << current->flightNumber << " ";
        current = current->next;
    }
    std::cout << std::endl;
}

int main() {
    FlightNode *head = nullptr;
    addFlight(head, 101);
    addFlight(head, 102);
    addFlight(head, 103);
    printFlights(head);
    removeFlight(head, 102);
    printFlights(head);
    // Iterator invalidation occurs here
    FlightNode *current = head;
    while (current != nullptr) {
        if (current->flightNumber == 101) {
            removeFlight(head, 101);
        }
        current = current->next;
    }
    printFlights(head);
    return 0;
}

