// Tries and prefix trees implementation for e-commerce shopping cart
class ShoppingCart {
  private:
    struct TrieNode {
        std::unordered_map<char, TrieNode *> children;
        bool isEndOfWord;
    };
    TrieNode *root;

  public:
    ShoppingCart() : root(new TrieNode()) {
    }
    ~ShoppingCart() {
        delete root;
    }
    void addProduct(const std::string &product) {
        TrieNode *currentNode = root;
        for (char c : product) {
            if (currentNode->children.find(c) == currentNode->children.end()) {
                currentNode->children[c] = new TrieNode();
            }
            currentNode = currentNode->children[c];
        }
        currentNode->isEndOfWord = true;
    }
    bool searchProduct(const std::string &product) {
        TrieNode *currentNode = root;
        for (char c : product) {
            if (currentNode->children.find(c) == currentNode->children.end()) {
                return false;
            }
            currentNode = currentNode->children[c];
        }
        return currentNode->isEndOfWord;
    }
    bool traverseAndPrint(TrieNode *node, const std::string &prefix) {
        if (node->isEndOfWord) {
            std::cout << prefix << std::endl;
        }
        for (const auto &child : node->children) {
            traverseAndPrint(node, prefix + child.first);
        }
        return true;
    }
    void printAllProducts() {
        traverseAndPrint(root, "");
    }
};

int main() {
