// Binary search tree node insertion and deletion
// for a flight reservation system

class Node {
  public:
    int passengerId;
    Node *left;
    Node *right;

    Node(int id) {
        passengerId = id;
        left = nullptr;
        right = nullptr;
    }
};

class FlightReservationSystem {
  public:
    Node *root;

    FlightReservationSystem() {
        root = nullptr;
    }

    void insertPassenger(int passengerId) {
        Node *newNode = new Node(passengerId);
        if (root == nullptr) {
            root = newNode;
        } else {
            insertRecursive(root, newNode);
        }
    }

    void insertRecursive(Node *current, Node *newNode) {
        if (newNode->passengerId < current->passengerId) {
            if (current->left == nullptr) {
                current->left = newNode;
            } else {
                insertRecursive(current->left, newNode);
            }
        } else {
            if (current->right == nullptr) {
                current->right = newNode;
            } else {
                insertRecursive(current->right, newNode);
            }
        }
    }

    void deletePassenger(int passengerId) {
        root = deleteRecursive(root, passengerId);
    }

    Node *deleteRecursive(Node *current, int passengerId) {
        if (current == nullptr) {
            return current;
        }
        if (passengerId < current->passengerId) {
            current->left = deleteRecursive(current->left, passengerId);
        } else if (passengerId > current->passengerId) {
            current->right = deleteRecursive(current->right, passengerId);
        } else {
            if (current->left == nullptr && current->right == nullptr) {
                return nullptr;
            } else if (current->left == nullptr) {
                return current->right;
            } else if (current->right == nullptr) {
                return current->left;
            } else {
                // Find the node with the minimum passengerId in the right
                // subtree
                Node *temp = current->right;
                while (temp->left != nullptr) {
                    temp = temp->left;
                }
                current->passengerId = temp->passengerId;
                current->right =
                    deleteRecursive(current->right, temp->passengerId);
            }
        }
        return current;
    }
};

int main() {
    FlightReservationSystem system;
    system.insertPassenger(10);
    system.insertPassenger(20);
    system.insertPassenger(5);
    system.deletePassenger(10);
    return 0;
}

