void removePost(Node *&head, int postId) {
    if (head == nullptr) {
        return;
    }
    if (head->postId == postId) {
        Node *temp = head;
        head = head->next;
        delete temp;
        return;
    }
    Node *current = head;
    while (current->next != nullptr) {
        if (current->next->postId == postId) {
            Node *temp = current->next;
            current->next = current->next->next;
            delete temp;
            return;
        }
        current = current->next;
    }
}

