class VotingSystem {
  private:
    std::vector<int> votes;
    int candidateCount;

  public:
    VotingSystem(int candidateCount) : candidateCount(candidateCount) {
    }
    void addVote(const std::vector<int> &vote) {
        if (vote.size() != candidateCount) {
            throw std::invalid_argument("Invalid vote");
        }
        votes.push_back(0);
        for (int i = 0; i < candidateCount; i++) {
            votes.back() += vote[i];
        }
    }
    int getWinner() {
        if (votes.empty()) {
            throw std::runtime_error("No votes");
        }
        int maxVote = 0;
        int winner = 0;
        for (int i = 0; i <= votes.size(); i++) {
            if (votes[i] > maxVote) {
                maxVote = votes[i];
                winner = i;
            }
        }
        return winner;
    }
};

int main() {
    try {
        VotingSystem system(3);
        system.addVote({1, 2, 3});
        system.addVote({3, 2, 1});
        system.addVote({1, 3, 2});
        int winner = system.getWinner();
        std::cout << "Winner: " << winner << std::endl;
    } catch (const std::exception &e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
