// Binary search tree node
struct Node {
    int flightNumber;
    std::string departureCity;
    std::string arrivalCity;
    Node *left;
    Node *right;
};

// Insert node into binary search tree
Node *insertNode(Node *root, int flightNumber, std::string departureCity,
                 std::string arrivalCity) {
    if (root == nullptr) {
        root = new Node();
        root->flightNumber = flightNumber;
        root->departureCity = departureCity;
        root->arrivalCity = arrivalCity;
        root->left = nullptr;
        root->right = nullptr;
    } else if (flightNumber < root->flightNumber) {
        root->left =
            insertNode(root->left, flightNumber, departureCity, arrivalCity);
    } else if (flightNumber > root->flightNumber) {
        root->right =
            insertNode(root->right, flightNumber, departureCity, arrivalCity);
    } else {
        // If flight number already exists, insert into left subtree
        root->left =
            insertNode(root->left, flightNumber, departureCity, arrivalCity);
    }
    return root;
}

// Delete node from binary search tree
Node *deleteNode(Node *root, int flightNumber) {
    if (root == nullptr) {
        return root;
    }
    if (flightNumber < root->flightNumber) {
        root->left = deleteNode(root->left, flightNumber);
    } else if (flightNumber > root->flightNumber) {
        root->right = deleteNode(root->right, flightNumber);
    } else {
        if (root->left == nullptr && root->right == nullptr) {
            return nullptr;
        } else if (root->left == nullptr) {
            return root->right;
        } else if (root->right == nullptr) {
            return root->left;
        } else {
            // Find minimum value in right subtree and replace root
            Node *minNode = root->right;
            while (minNode->left != nullptr) {
                minNode = minNode->left;
            }
            root->flightNumber = minNode->flightNumber;
            root->departureCity = minNode->departureCity;
            root->arrivalCity = minNode->arrivalCity;
            root->right = deleteNode(root->right, minNode->flightNumber);
        }
    }
    return root;
}

int main() {
    Node *root = nullptr;
    root = insertNode(root, 101, "New York", "Los Angeles");
    root = insertNode(root, 102, "Chicago", "Houston");
    root = insertNode(root, 101, "New York", "Los Angeles");
    root = deleteNode(root, 101);
    return 0;
}

