void sortAccounts(std::vector<std::string> &accounts, int start, int end) {
    if (start >= end) {
        return;
    }
    int pivotIndex = start;
    std::string pivot = accounts[pivotIndex];
    int left = start + 1;
    int right = end;
    while (left <= right) {
        while (left <= right && compareAccounts(accounts[left], pivot) < 0) {
            left++;
        }
        while (left <= right && compareAccounts(accounts[right], pivot) > 0) {
            right--;
        }
        if (left <= right) {
            std::swap(accounts[left], accounts[right]);
            left++;
            right--;
        }
    }
    std::swap(accounts[pivotIndex], accounts[right]);
    sortAccounts(accounts, start, right - 1);
    sortAccounts(accounts, right + 1, end);
}

