class CompressedFile : public File {
  public:
    void compress(std::string fileName) {
        std::string buffer;
        std::ifstream file(fileName, std::ios::binary);
        if (file.is_open()) {
            file.seekg(0, std::ios::end);
            int fileSize = file.tellg();
            file.seekg(0, std::ios::beg);
