class GameInventory {
  private:
    TrieNode *root;

  public:
    GameInventory() : root(new TrieNode("", 0)) {
    }
    ~GameInventory() {
        delete root;
    }
    void addItem(std::string itemName, int quantity) {
        TrieNode *currentNode = root;
        for (char c : itemName) {
            bool found = false;
            for (TrieNode *child : currentNode->children) {
                if (child->itemName == std::string(1, c)) {
                    currentNode = child;
                    found = true;
                    break;
                }
            }
            if (!found) {
                TrieNode *newNode =
                    new TrieNode(std::string(itemName), quantity);
                currentNode->children.push_back(newNode);
                currentNode = newNode;
            }
        }
    }
};
