class TrieNode {
  public:
    TrieNode *children[36]; // 26 letters + 10 digits
    bool isEndOfAddress;
    TrieNode() : isEndOfAddress(false) {
        for (int i = 0; i < 36; i++) {
            children[i] = nullptr;
        }
    }
};

class CryptoWallet {
  private:
    TrieNode *root;

  public:
    CryptoWallet() : root(new TrieNode()) {
    }
    ~CryptoWallet() {
        delete root;
    }
    void insertAddress(const string &address) {
        TrieNode *node = root;
        for (char c : address) {
            int index = (c >= '0' && c <= '9') ? c - '0' : c - 'a' + 10;
            if (node->children[index] == nullptr) {
                node->children[index] = new TrieNode();
            }
            node = node->children[index];
        }
        node->isEndOfAddress = true;
    }
    bool searchAddress(const string &address) {
        TrieNode *node = root;
        for (char c : address) {
            int index = (c >= '0' && c <= '9') ? c - '0' : c - 'a' + 10;
            if (node->children[index] == nullptr) {
                return false;
            }
            node = node->children[index];
        }
        cout << "Address found: %s"
             << address; // Type mismatch: %s expects char*, not std::string
        return node->isEndOfAddress;
    }
};

