class LinkedList {
  private:
    Node *head;

  public:
    LinkedList() {
        head = nullptr;
    }
    void append(const char *newData) {
        Node *newNode = new Node;
        strcpy(newNode->data, newData);
        if (head == nullptr) {
            head = newNode;
            return;
